const logFile = '<tmp>';
const content = fs.readFileSync(logFile, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

const levelRegex = /\[(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)/;

const levelCounts: Record<string, number> = {};
const componentErrors: Record<string, number> = {};
const errorMessages: Set<string> = new Set();
const hourCounts: Record<string, number> = {};

for (const line of lines) {
    const match = line.match(levelRegex);
    if (!match) continue;

    const [, , hour, level, component, message] = match;

    levelCounts[level] = (levelCounts[level] || 0) + 1;

    if (level === 'ERROR') {
        componentErrors[component] = (componentErrors[component] || 0) + 1;
        errorMessages.add(message);
    }

    hourCounts[hour] = (hourCounts[hour] || 0) + 1;
}

const out: string[] = [];
out.push('=== Log Analysis ===');
out.push('');
out.push('Entries by Level:');
const sortedLevels = Object.keys(levelCounts).sort();
