let maxComponent = '';
const sortedComps = Object.keys(componentErrors).sort();
for (const comp of sortedComps) {
    if (componentErrors[comp] > maxErrors) {
        maxErrors = componentErrors[comp];
        maxComponent = comp;
    }
}
out.push(`Component with Most Errors: ${maxComponent} (${maxErrors} errors)`);
out.push('');

out.push('Unique Error Messages:');
const sortedMessages = Array.from(errorMessages).sort();
for (const msg of sortedMessages) {
    out.push(`  - ${msg}`);
}
out.push('');

let maxHourCount = -1;
let maxHour = '';
const sortedHours = Object.keys(hourCounts).sort();
for (const h of sortedHours) {
    if (hourCounts[h] > maxHourCount) {
        maxHourCount = hourCounts[h];
        maxHour = h;
    }
}
out.push(`Busiest Hour: ${maxHour}:00 (${maxHourCount} entries)`);

process.stdout.write(out.join('\n') + '\n');

