import * as fs from 'fs';

function formatMoney(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const parts = fixed.split('.');
  let intPart = parts[0];
  let decPart = parts.length > 1 ? '.' + parts[1] : '';
  const negative = intPart.startsWith('-');
  if (negative) intPart = intPart.slice(1);
  intPart = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return '$' + (negative ? '-' : '') + intPart + decPart;
}

const csvPath = '<tmp>';
const csvContent = fs.readFileSync(csvPath, 'utf-8').replace(/^\uFEFF/, '');

const lines = csvContent.trim().split('\n');
const employees: { name: string; department: string; salary: number }[] = [];

for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const cols = line.split(',').map(c => c.trim());
  if (cols.length < 4) continue;
  employees.push({
    name: cols[1],
    department: cols[2],
    salary: parseFloat(cols[3])
  });
}

const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
  if (!deptSalaries.has(emp.department)) deptSalaries.set(emp.department, []);
  deptSalaries.get(emp.department)!.push(emp.salary);
}

const sortedDepts = Array.from(deptSalaries.keys()).sort();

let highestEmp = employees[0];
for (const emp of employees) {
  if (emp.salary > highestEmp.salary) highestEmp = emp;
}

const deptCounts: Map<string, number> = new Map();
for (const emp of employees) {
  deptCounts.set(emp.department, (deptCounts.get(emp.department) || 0) + 1);
}
const deptsWithMoreThan2 = Array.from(deptCounts.entries())
  .filter(([, count]) => count > 2)
  .sort((a, b) => a[0].localeCompare(b[0]));

const totalBudget = employees.reduce((sum, emp) => sum + emp.salary, 0);

const out: string[] = [];
out.push('=== Salary Report ===');
out.push('');
out.push('Average Salary by Department:');
for (const dept of sortedDepts) {
  const salaries = deptSalaries.get(dept)!;
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  out.push(`  ${dept}: ${formatMoney(avg, 2)}`);
}
out.push('');
out.push(`Highest Paid: ${highestEmp.name} (${formatMoney(highestEmp.salary, 0)})`);
out.push('');
out.push('Departments with >2 employees:');
for (const [dept, count] of deptsWithMoreThan2) {
  out.push(`  ${dept} (${count} employees)`);
}
out.push('');
out.push(`Total Budget: ${formatMoney(totalBudget, 0)}`);

process.stdout.write(out.join('\n') + '\n');
