use std::collections::HashMap;
use std::fs;

fn format_int_commas(n: i64) -> String {
    let abs = if n < 0 { -n } else { n };
    let s = abs.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if n < 0 {
        format!("-{}", result)
    } else {
        result
    }
}

fn format_money_2dp(n: f64) -> String {
    let rounded = (n * 100.0).round() / 100.0;
    let int_part = rounded as i64;
    let dec_part = ((rounded - int_part as f64) * 100.0).round() as i64;
    format!("${}.{:02}", format_int_commas(int_part), dec_part)
}

fn format_money_int(n: f64) -> String {
    let int_val = n.round() as i64;
    format!("${}", format_int_commas(int_val))
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut lines = content.lines();
    lines.next(); // skip header

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut max_salary: f64 = f64::MIN;
    let mut max_name: String = String::new();
    let mut total_budget: f64 = 0.0;

    for line in lines {
        let line = line.trim().trim_end_matches('\r');
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|f| f.trim()).collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        dept_salaries
            .entry(department.clone())
            .or_insert_with(Vec::new)
            .push(salary);

        if salary > max_salary {
            max_salary = salary;
            max_name = name.clone();
        }

        total_budget += salary;
    }

    let mut depts: Vec<&String> = dept_salaries.keys().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let salaries = &dept_salaries[*dept];
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: {}", dept, format_money_2dp(avg));
    }
    println!();
    println!("Highest Paid: {} ({})", max_name, format_money_int(max_salary));
    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let count = dept_salaries[*dept].len();
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: {}", format_money_int(total_budget));
}

