func canonicalKey(_ obj: Any) -> String {
    let data = try! JSONSerialization.data(withJSONObject: obj, options: [.sortedKeys])
    return String(data: data, encoding: .utf8)!
}

func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var result: [String: Any] = [:]
        for (key, value) in dictA {
            result[key] = value
        }
        for (key, value) in dictB {
            if let aVal = dictA[key] {
                result[key] = deepMerge(aVal, value)
            } else {
                result[key] = value
            }
        }
        return result
    }
    if let arrA = a as? [Any], let arrB = b as? [Any] {
        var result: [Any] = []
        var seen = Set<String>()
        for item in arrA {
            let key = canonicalKey(item)
            if !seen.contains(key) {
                seen.insert(key)
                result.append(item)
            }
        }
        for item in arrB {
            let key = canonicalKey(item)
            if !seen.contains(key) {
                seen.insert(key)
                result.append(item)
            }
        }
        return result
    }
    return b
}

