use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = line.find(']').expect("No closing bracket found");
        let timestamp_part = &line[1..close_bracket];

        // Extract hour from "YYYY-MM-DD HH:MM:SS"
        let hour: u32 = timestamp_part[11..13].parse().expect("Invalid hour");

        // After ']'
        let rest = line[close_bracket + 1..].trim_start();

        // Extract level (word before next space)
        let level_end = rest.find(' ').expect("No level found");
        let level = &rest[..level_end];

        // After level, expect " (component) - message"
        let after_level = rest[level_end..].trim_start();

        // Extract component between ( and )
        let paren_start = after_level.find('(').expect("No opening paren");
        let paren_end = after_level.find(')').expect("No closing paren");
        let component = &after_level[paren_start + 1..paren_end];

        // After ')', expect " - message"
        let after_component = after_level[paren_end + 1..].trim_start();
        let msg_start = after_component.find(" - ").expect("No message separator");
        let message = &after_component[msg_start + 3..];

        *level_counts.entry(level.to_string()).or_insert(0) += 1;
        *hour_counts.entry(hour).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let max_err = error_component_counts.values().max().copied().unwrap_or(0);
    let top_component = error_component_counts.iter()
        .filter(|(_, c)| **c == max_err)
        .map(|(name, _)| name)
        .min()
        .expect("No errors found");
    println!("Component with Most Errors: {} ({} errors)", top_component, max_err);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
