    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = line.find(']').expect("No closing bracket found");
        let timestamp_part = &line[1..close_bracket];

        // Extract hour from "YYYY-MM-DD HH:MM:SS"
        let hour: u32 = timestamp_part[11..13].parse().expect("Invalid hour");

        // After ']'
        let rest = line[close_bracket + 1..].trim_start();

        // Extract level (word before next space)
        let level_end = rest.find(' ').expect("No level found");
        let level = &rest[..level_end];

        // After level, expect " (component) - message"
        let after_level = rest[level_end..].trim_start();

        // Extract component between ( and )
        let paren_start = after_level.find('(').expect("No opening paren");
        let paren_end = after_level.find(')').expect("No closing paren");
        let component = &after_level[paren_start + 1..paren_end];

