        let after_component = after_level[paren_end + 1..].trim_start();
        let msg_start = after_component.find(" - ").expect("No message separator");
        let message = &after_component[msg_start + 3..];

        *level_counts.entry(level.to_string()).or_insert(0) += 1;
        *hour_counts.entry(hour).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
