#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static void format_comma(double val, int decimals, char *buf, size_t bufsize) {
    char tmp[64];
    if (decimals == 0) {
        snprintf(tmp, sizeof(tmp), "%.0f", val);
    } else {
        snprintf(tmp, sizeof(tmp), "%.*f", decimals, val);
    }
    int len = (int)strlen(tmp);
    int dot_pos = -1;
    for (int i = 0; i < len; i++) {
        if (tmp[i] == '.') { dot_pos = i; break; }
    }
    int int_len = (dot_pos == -1) ? len : dot_pos;
    int pos = 0;
    int first = 1;
    for (int i = 0; i < int_len; i++) {
        if (first) {
            buf[pos++] = tmp[i];
            first = 0;
        } else {
            int remaining = int_len - i;
            if (remaining > 1 && remaining % 3 == 0) {
                buf[pos++] = ',';
            }
            buf[pos++] = tmp[i];
        }
    }
    if (dot_pos != -1) {
        buf[pos++] = '.';
        for (int i = dot_pos + 1; i < len; i++) {
            buf[pos++] = tmp[i];
        }
    }
    buf[pos] = '\0';
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file\n");
        return 1;
    }

    char *line = malloc(8192);
    if (!line) { fclose(f); return 1; }

    if (fgets(line, 8192, f) == NULL) {
        fclose(f);
        free(line);
        return 1;
    }

    int cap = 256;
    int n = 0;
    char **names = malloc(cap * sizeof(char *));
    char **depts = malloc(cap * sizeof(char *));
    double *salaries = malloc(cap * sizeof(double));

    while (fgets(line, 8192, f)) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;

        char *fields[6] = {0};
        int nf = 0;
        char *p = line;
        fields[nf++] = p;
        while (*p) {
            if (*p == ',') {
                *p = '\0';
                fields[nf++] = p + 1;
            }
            p++;
        }

        if (nf < 4) continue;

        if (n >= cap) {
            cap *= 2;
            names = realloc(names, cap * sizeof(char *));
            depts = realloc(depts, cap * sizeof(char *));
            salaries = realloc(salaries, cap * sizeof(double));
        }

        names[n] = strdup(fields[1]);
        depts[n] = strdup(fields[2]);

        /* strip $ and commas from salary field */
        char *sf = fields[3];
        while (*sf == '$' || *sf == ' ') sf++;
        /* remove commas */
        char *w = sf;
        for (char *r = sf; *r; r++) {
            if (*r != ',') *w++ = *r;
        }
        *w = '\0';
        salaries[n] = atof(sf);
        n++;
    }

    fclose(f);
    free(line);

    if (n == 0) {
        free(names); free(depts); free(salaries);
        return 0;
    }

    /* Build unique sorted department list */
    int dcap = 256;
    int dcount = 0;
    char **unique_depts = malloc(dcap * sizeof(char *));

    for (int i = 0; i < n; i++) {
        int found = 0;
        for (int j = 0; j < dcount; j++) {
            if (strcmp(unique_depts[j], depts[i]) == 0) { found = 1; break; }
        }
        if (!found) {
            if (dcount >= dcap) {
                dcap *= 2;
                unique_depts = realloc(unique_depts, dcap * sizeof(char *));
            }
            unique_depts[dcount++] = strdup(depts[i]);
        }
    }

    qsort(unique_depts, dcount, sizeof(char *), cmp_str);

    double *dept_total = calloc(dcount, sizeof(double));
    int *dept_count = calloc(dcount, sizeof(int));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < dcount; j++) {
            if (strcmp(unique_depts[j], depts[i]) == 0) {
                dept_total[j] += salaries[i];
                dept_count[j]++;
                break;
            }
        }
    }

    /* Highest paid */
    int max_idx = 0;
    for (int i = 1; i < n; i++) {
        if (salaries[i] > salaries[max_idx]) max_idx = i;
    }

    /* Total budget */
    double total_budget = 0;
    for (int i = 0; i < n; i++) total_budget += salaries[i];

    /* Print */
    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < dcount; i++) {
        double avg = dept_total[i] / dept_count[i];
        char buf[64];
        format_comma(avg, 2, buf, sizeof(buf));
        printf("  %s: $%s\n", unique_depts[i], buf);
    }
    printf("\n");

    {
        char buf[64];
        format_comma(salaries[max_idx], 0, buf, sizeof(buf));
        printf("Highest Paid: %s ($%s)\n", names[max_idx], buf);
    }
    printf("\n");

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dcount; i++) {
        if (dept_count[i] > 2) {
            printf("  %s (%d employees)\n", unique_depts[i], dept_count[i]);
        }
    }
    printf("\n");

    {
        char buf[64];
        format_comma(total_budget, 0, buf, sizeof(buf));
        printf("Total Budget: $%s\n", buf);
    }

    /* Cleanup */
    for (int i = 0; i < n; i++) { free(names[i]); free(depts[i]); }
    free(names); free(depts); free(salaries);
    for (int i = 0; i < dcount; i++) free(unique_depts[i]);
    free(unique_depts);
    free(dept_total);
    free(dept_count);

    return 0;
}

