        Json::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let mut parts = Vec::new();
                for item in arr {
                    parts.push(format!(
                        "{}{}",
                        pad_inner,
                        serialize_json(item, indent + 1)
