                    parts.push(format!(
                        "{}\"{}\": {}",
                        pad_inner,
                        escape_string(k),
                        serialize_json(v, indent + 1)
                    ));
                }
                format!("{{\n{}\n{}}}", parts.join(",\n"), pad)
            }
        }
