/* ---------- Deep Equality ---------- */

static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->num_val == b->num_val;
        case JSON_STRING: return a->str_val && b->str_val && strcmp(a->str_val, b->str_val) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++)
                if (!json_equal(a->items[i], b->items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->pair_count != b->pair_count) return 0;
            for (int i = 0; i < a->pair_count; i++) {
                int found = 0;
                for (int j = 0; j < b->pair_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equal(a->values[i], b->values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

/* ---------- Deep Merge ---------- */

static json_value *deep_merge(const json_value *a, const json_value *b) {
    /* If both are objects, merge recursively */
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new();
        result->type = JSON_OBJECT;
        /* Collect all unique keys from A and B */
        int total = a->pair_count + b->pair_count;
        result->pair_cap = total > 0 ? total : 8;
        result->keys = (char **)calloc(result->pair_cap, sizeof(char *));
        result->values = (json_value **)calloc(result->pair_cap, sizeof(json_value *));
        if (!result->keys || !result->values) { fprintf(stderr, "OOM\n"); exit(1); }

        for (int i = 0; i < a->pair_count; i++) {
            /* Check if key exists in B */
            int found_in_b = -1;
            for (int j = 0; j < b->pair_count; j++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) { found_in_b = j; break; }
            }
            if (found_in_b >= 0) {
                result->keys[result->pair_count] = strdup(a->keys[i]);
                result->values[result->pair_count] = deep_merge(a->values[i], b->values[found_in_b]);
                result->pair_count++;
            } else {
                result->keys[result->pair_count] = strdup(a->keys[i]);
                result->values[result->pair_count] = a->values[i]; /* borrow pointer - we won't free a later */
                result->pair_count++;
            }
        }
        for (int j = 0; j < b->pair_count; j++) {
            int found_in_a = -1;
            for (int i = 0; i < a->pair_count; i++) {
                if (strcmp(b->keys[j], a->keys[i]) == 0) { found_in_a = i; break; }
            }
            if (found_in_a < 0) {
                result->keys[result->pair_count] = strdup(b->keys[j]);
                result->values[result->pair_count] = b->values[j];
                result->pair_count++;
            }
        }
        return result;
    }

    /* If both are arrays, concatenate and dedup */
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new();
        result->type = JSON_ARRAY;
        int cap = a->item_count + b->item_count;
        if (cap < 1) cap = 1;
        result->item_cap = cap;
        result->items = (json_value **)calloc(result->item_cap, sizeof(json_value *));
        if (!result->items) { fprintf(stderr, "OOM\n"); exit(1); }

        /* Add all items from A */
        for (int i = 0; i < a->item_count; i++) {
            result->items[result->item_count++] = a->items[i];
        }
        /* Add items from B that are not already in result */
        for (int i = 0; i < b->item_count; i++) {
            int dup = 0;
            for (int j = 0; j < result->item_count; j++) {
                if (json_equal(result->items[j], b->items[i])) { dup = 1; break; }
            }
            if (!dup) {
                result->items[result->item_count++] = b->items[i];
            }
        }
        return result;
    }

    /* Scalar conflict or type mismatch: B overrides A */
    if (b->type == JSON_OBJECT) {
        json_value *result = json_new();
        result->type = JSON_OBJECT;
        result->pair_cap = b->pair_count > 0 ? b->pair_count : 1;
        result->keys = (char **)calloc(result->pair_cap, sizeof(char *));
        result->values = (json_value **)calloc(result->pair_cap, sizeof(json_value *));
        for (int i = 0; i < b->pair_count; i++) {
            result->keys[i] = strdup(b->keys[i]);
            result->values[i] = b->values[i];
        }
        result->pair_count = b->pair_count;
        return result;
    }
    if (b->type == JSON_ARRAY) {
        json_value *result = json_new();
        result->type = JSON_ARRAY;
        result->item_cap = b->item_count > 0 ? b->item_count : 1;
        result->items = (json_value **)calloc(result->item_cap, sizeof(json_value *));
        for (int i = 0; i < b->item_count; i++) result->items[i] = b->items[i];
        result->item_count = b->item_count;
        return result;
    }
    /* Scalar: just return b (shallow copy) */
    json_value *result = json_new();
    result->type = b->type;
    result->bool_val = b->bool_val;
    result->num_val = b->num_val;
    if (b->type == JSON_STRING) result->str_val = strdup(b->str_val);
    return result;
}

/* ---------- Pretty Print with Sorted Keys ---------- */

static void print_string_escaped(FILE *f, const char *s) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (c < 0x20) fprintf(f, "\\u%04x", c);
                else fputc(c, f);
        }
    }
    fputc('"', f);
}

static void print_number(FILE *f, double val) {
    if (val == (double)(long long)val && fabs(val) < 1e18) {
        fprintf(f, "%lld", (long long)val);
    } else {
        /* Use %g but ensure it looks like JSON */
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", val);
        /* Check if it has a decimal point or exponent to distinguish from int */
        int has_dot = 0, has_exp = 0;
        for (char *p = buf; *p; p++) {
            if (*p == '.' || *p == 'e' || *p == 'E') { has_dot = 1; has_exp = 1; break; }
        }
        if (!has_dot && !has_exp) {
            /* It printed as integer, add .0 */
            fprintf(f, "%s.0", buf);
        } else {
            fprintf(f, "%s", buf);
        }
    }
}

static void print_value(FILE *f, const json_value *v, int indent) {
    switch (v->type) {
        case JSON_NULL:
            fprintf(f, "null");
            break;
        case JSON_BOOL:
