                idx[j + 1] = key;
            }
            fprintf(f, "{\n");
            for (int i = 0; i < n; i++) {
                int ki = idx[i];
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', f);
                print_string_escaped(f, v->keys[ki]);
                fprintf(f, ": ");
                print_value(f, v->values[ki], indent + 1);
                if (i < n - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', f);
            fputc('}', f);
            free(idx);
            break;
        }
    }
}

/* ---------- File Reading ---------- */

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    *out_len = rd;
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    size_t len_a, len_b;
    char *text_a = read_file(path_a, &len_a);
    char *text_b = read_file(path_b, &len_b);

    json_value *a = parse_json(text_a, len_a);
    json_value *b = parse_json(text_b, len_b);
    if (!a || !b) {
        fprintf(stderr, "JSON parse error\n");
        return 1;
    }

    json_value *merged = deep_merge(a, b);

    print_value(stdout, merged, 0);
    fputc('\n', stdout);

    /* Cleanup: merged owns pointers that are shared with a and b,
       so we only free the structural wrappers of a and b, not their children.
       Actually, let's just free everything - the merged object borrows pointers
       from a and b. We need to be careful. Let's just free a and b structurally
       but not their children since merged references them. */
    /* Simplest: just free the top-level wrappers without recursing into children */
    free(a->keys); free(a->values); free(a->items); free(a->str_val); free(a);
    free(b->keys); free(b->values); free(b->items); free(b->str_val); free(b);
    json_free(merged);
    free(text_a);
    free(text_b);

    return 0;
}
