        for (int i = start; i < s.length(); i++) {
            if (s.charAt(i) == '"') {
                int backslashes = 0;
                int j = i - 1;
                while (j >= 0 && s.charAt(j) == '\\') {
                    backslashes++;
                    j--;
                }
                if (backslashes % 2 == 0) return i;
            }
        }
        return s.length();
    }

