#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;

    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }
    buf[0] = '\0';

    size_t total = 0;
    size_t n;
    while ((n = fread(buf + total, 1, cap - total - 1, fp)) > 0) {
        total += n;
        if (total >= cap - 1) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = tmp;
        }
        buf[total] = '\0';
    }

    pclose(fp);

    while (total > 0 &&
           (buf[total - 1] == '\n' || buf[total - 1] == '\r' ||
            buf[total - 1] == ' '  || buf[total - 1] == '\t')) {
        buf[--total] = '\0';
    }

    return buf;
}

int main(void)
{
    char *hostname = run_command("hostname");
    char *os       = run_command("uname -s");
    char *arch     = run_command("uname -m");
