const A: number[][] = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
const B: number[][] = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];

function multiply(A: number[][], B: number[][]): number[][] {
    const n = A.length;
    const C: number[][] = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            for (let k = 0; k < n; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = M.filter((_, i) => i !== 0).map(row => row.filter((_, k) => k !== j));
        det += ((j % 2 === 0 ? 1 : -1) * M[0][j] * determinant(minor));
    }
    return det;
}

function formatRow(row: number[]): string {
    return "  " + row.map(v => v.toString().padStart(4)).join(" ");
}

function printMatrix(m: number[][]): string {
    return m.map(formatRow).join("\n");
}

