    const C: number[][] = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            for (let k = 0; k < n; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = M.filter((_, i) => i !== 0).map(row => row.filter((_, k) => k !== j));
        det += ((j % 2 === 0 ? 1 : -1) * M[0][j] * determinant(minor));
    }
    return det;
}

function formatRow(row: number[]): string {
    return "  " + row.map(v => v.toString().padStart(4)).join(" ");
}

function printMatrix(m: number[][]): string {
    return m.map(formatRow).join("\n");
}

const C = multiply(A, B);
const det = determinant(C);

let out = "";
out += "=== Matrix Operations ===\n";
out += "\n";
out += "Matrix A:\n";
out += printMatrix(A) + "\n";
out += "\n";
out += "Matrix B:\n";
out += printMatrix(B) + "\n";
out += "\n";
out += "A x B =\n";
out += printMatrix(C) + "\n";
out += "\n";
out += "Determinant: " + det + "\n";

process.stdout.write(out);
