import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileStats {
  relativePath: string;
  lines: number;
  chars: number;
}

function getExtension(filename: string): string {
  const lastDot = filename.lastIndexOf('.');
  if (lastDot === -1 || lastDot === 0) return '';
  return filename.substring(lastDot);
}

function countLines(content: Buffer): number {
  if (content.length === 0) return 0;
  const text = content.toString('utf-8');
  let lines = (text.match(/\n/g) || []).length;
  if (!text.endsWith('\n')) {
    lines += 1;
  }
  return lines;
}

function walkDir(dir: string, rootDir: string, visited: Set<string>): FileStats[] {
  const results: FileStats[] = [];

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (!visited.has(realPath)) {
        visited.add(realPath);
        const subResults = walkDir(fullPath, rootDir, visited);
        results.push(...subResults);
      }
    } else if (entry.isFile()) {
      const relativePath = path.relative(rootDir, fullPath).split(path.sep).join('/');
      const content = fs.readFileSync(fullPath);
      const chars = content.length;
      const lines = countLines(content);
      results.push({ relativePath, lines, chars });
    }
  }

  return results;
}

function main(): void {
  const visited = new Set<string>();
  let rootReal: string;
  try {
    rootReal = fs.realpathSync(rootDir);
  } catch {
    rootReal = rootDir;
  }
  visited.add(rootReal);

  const allFiles = walkDir(rootDir, rootDir, visited);

  const groups = new Map<string, FileStats[]>();
  for (const f of allFiles) {
    const ext = getExtension(path.basename(f.relativePath));
    if (!groups.has(ext)) {
      groups.set(ext, []);
    }
    groups.get(ext)!.push(f);
  }

  const sortedExts = Array.from(groups.keys()).sort();

  for (const ext of sortedExts) {
    groups.get(ext)!.sort((a, b) =>
      a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0
    );
  }

  const output: string[] = [];
  output.push('=== File Tree Analysis ===');
  output.push('');

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  for (const ext of sortedExts) {
    const files = groups.get(ext)!;
    const extLines = files.reduce((s, f) => s + f.lines, 0);
    const extChars = files.reduce((s, f) => s + f.chars, 0);

    output.push(`Extension: ${ext}`);
    output.push(`  Files: ${files.length}`);
    output.push(`  Total Lines: ${extLines}`);
    output.push(`  Total Characters: ${extChars}`);
    for (const f of files) {
      output.push(`    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars`);
    }

    totalFiles += files.length;
    totalLines += extLines;
    totalChars += extChars;
  }

  output.push('');
  output.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

  process.stdout.write(output.join('\n') + '\n');
}

main();

