#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int count;
} LevelEntry;

typedef struct {
    char *name;
    int count;
} CompEntry;

typedef struct {
    char *msg;
} MsgEntry;

static int cmp_level(const void *a, const void *b) {
    const LevelEntry *ea = (const LevelEntry *)a;
    const LevelEntry *eb = (const LevelEntry *)b;
    return strcmp(ea->name, eb->name);
}

static int cmp_msg(const void *a, const void *b) {
    const MsgEntry *ea = (const MsgEntry *)a;
    const MsgEntry *eb = (const MsgEntry *)b;
    return strcmp(ea->msg, eb->msg);
}

int main(void) {
    const char *filename = "<tmp>";
    FILE *f = fopen(filename, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    char *line = NULL;
    size_t linecap = 0;
    ssize_t linelen;

    LevelEntry *levels = NULL;
    int nlevels = 0, caplevels = 0;

    CompEntry *comps = NULL;
    int ncomps = 0, capcomps = 0;

    MsgEntry *msgs = NULL;
    int nmsgs = 0, capmsgs = 0;

    int hours[24] = {0};

    while ((linelen = getline(&line, &linecap, f)) != -1) {
        if (linelen > 0 && line[linelen - 1] == '\n') line[linelen - 1] = '\0';
        if (linelen > 0 && line[linelen - 1] == '\r') line[linelen - 1] = '\0';

        if (linelen < 22 || line[0] != '[') continue;

        /* hour at positions 12,13 (0-indexed) */
        if (line[11] == ' ' && line[12] >= '0' && line[12] <= '9' &&
            line[13] >= '0' && line[13] <= '9') {
            int hour = (line[12] - '0') * 10 + (line[13] - '0');
            if (hour >= 0 && hour < 24) hours[hour]++;
        }

        char *close_bracket = strchr(line, ']');
        if (!close_bracket) continue;

        char *q = close_bracket + 1;
        while (*q == ' ') q++;

        /* read LEVEL */
        char *level_start = q;
        while (*q && *q != ' ' && *q != '(') q++;
        char *level_end = q;
        while (level_end > level_start && level_end[-1] == ' ') level_end--;
        int level_len = (int)(level_end - level_start);
        if (level_len <= 0) continue;

        char *level_str = malloc(level_len + 1);
        memcpy(level_str, level_start, level_len);
        level_str[level_len] = '\0';

        /* skip to ( */
        while (*q == ' ') q++;
        if (*q != '(') { free(level_str); continue; }
        q++;

        /* read component */
        char *comp_start = q;
        while (*q && *q != ')') q++;
        if (*q != ')') { free(level_str); continue; }
        char *comp_end = q;
        int comp_len = (int)(comp_end - comp_start);
        if (comp_len <= 0) { free(level_str); continue; }

        char *comp_str = malloc(comp_len + 1);
        memcpy(comp_str, comp_start, comp_len);
        comp_str[comp_len] = '\0';

        q++; /* skip ) */
        while (*q == ' ') q++;
        if (*q != '-') { free(level_str); free(comp_str); continue; }
        q++;
        while (*q == ' ') q++;

        /* message */
        char *msg_start = q;
        int msg_len = (int)strlen(msg_start);
        char *msg_str = malloc(msg_len + 1);
        memcpy(msg_str, msg_start, msg_len);
        msg_str[msg_len] = '\0';

        /* add to levels */
        int found = 0;
        for (int i = 0; i < nlevels; i++) {
            if (strcmp(levels[i].name, level_str) == 0) {
                levels[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (nlevels == caplevels) {
                caplevels = caplevels ? caplevels * 2 : 16;
                levels = realloc(levels, caplevels * sizeof(LevelEntry));
            }
            levels[nlevels].name = level_str;
            levels[nlevels].count = 1;
            nlevels++;
        } else {
            free(level_str);
        }

        /* if ERROR, track component and message */
        if (strcmp(level_str, "ERROR") == 0) {
            found = 0;
            for (int i = 0; i < ncomps; i++) {
                if (strcmp(comps[i].name, comp_str) == 0) {
                    comps[i].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (ncomps == capcomps) {
                    capcomps = capcomps ? capcomps * 2 : 16;
                    comps = realloc(comps, capcomps * sizeof(CompEntry));
                }
                comps[ncomps].name = comp_str;
                comps[ncomps].count = 1;
                ncomps++;
            } else {
                free(comp_str);
            }

            found = 0;
            for (int i = 0; i < nmsgs; i++) {
                if (strcmp(msgs[i].msg, msg_str) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (nmsgs == capmsgs) {
                    capmsgs = capmsgs ? capmsgs * 2 : 64;
                    msgs = realloc(msgs, capmsgs * sizeof(MsgEntry));
                }
                msgs[nmsgs].msg = msg_str;
                nmsgs++;
            } else {
                free(msg_str);
            }
        } else {
            free(comp_str);
            free(msg_str);
        }
    }

    free(line);
    fclose(f);

    /* sort levels */
    if (nlevels > 0)
        qsort(levels, nlevels, sizeof(LevelEntry), cmp_level);

    /* sort messages */
    if (nmsgs > 0)
        qsort(msgs, nmsgs, sizeof(MsgEntry), cmp_msg);

    /* find component with most errors */
    int max_comp_idx = -1;
    int max_comp_count = 0;
    for (int i = 0; i < ncomps; i++) {
        if (comps[i].count > max_comp_count) {
            max_comp_count = comps[i].count;
