}

int main(void) {
    const char *filename = "<tmp>";
    FILE *f = fopen(filename, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    char *line = NULL;
    size_t linecap = 0;
    ssize_t linelen;

    LevelEntry *levels = NULL;
    int nlevels = 0, caplevels = 0;

    CompEntry *comps = NULL;
    int ncomps = 0, capcomps = 0;

    MsgEntry *msgs = NULL;
    int nmsgs = 0, capmsgs = 0;

    int hours[24] = {0};

