        char *level_start = q;
        while (*q && *q != ' ' && *q != '(') q++;
        char *level_end = q;
        while (level_end > level_start && level_end[-1] == ' ') level_end--;
        int level_len = (int)(level_end - level_start);
        if (level_len <= 0) continue;

        char *level_str = malloc(level_len + 1);
        memcpy(level_str, level_start, level_len);
