        while (*q == ' ') q++;
        if (*q != '(') { free(level_str); continue; }
        q++;

        /* read component */
        char *comp_start = q;
        while (*q && *q != ')') q++;
        if (*q != ')') { free(level_str); continue; }
        char *comp_end = q;
        int comp_len = (int)(comp_end - comp_start);
        if (comp_len <= 0) { free(level_str); continue; }

        char *comp_str = malloc(comp_len + 1);
        memcpy(comp_str, comp_start, comp_len);
        comp_str[comp_len] = '\0';

