use std::io::{Read, Write};
use std::net::TcpStream;

enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && (self.input[self.pos] as char).is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        if self.pos < self.input.len() { self.input[self.pos] } else { 0 }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_whitespace();
        if self.pos >= self.input.len() {
            return JsonValue::Null;
        }
        match self.peek() {
            b'[' => self.parse_array(),
            b'{' => self.parse_object(),
            b'"' => JsonValue::String(self.parse_string()),
            b't' => { self.pos += 4; JsonValue::Bool(true) }
            b'f' => { self.pos += 5; JsonValue::Bool(false) }
            b'n' => { self.pos += 4; JsonValue::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_array(&mut self) -> JsonValue {
        self.pos += 1;
        self.skip_whitespace();
        let mut items = Vec::new();
        if self.peek() == b']' {
            self.pos += 1;
            return JsonValue::Array(items);
        }
        loop {
            self.skip_whitespace();
            items.push(self.parse_value());
            self.skip_whitespace();
            if self.peek() == b',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.peek() == b']' { self.pos += 1; }
        JsonValue::Array(items)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.pos += 1;
        self.skip_whitespace();
        let mut map = Vec::new();
        if self.peek() == b'}' {
            self.pos += 1;
            return JsonValue::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            if self.peek() == b':' { self.pos += 1; }
            let value = self.parse_value();
            map.push((key, value));
            self.skip_whitespace();
            if self.peek() == b',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.peek() == b'}' { self.pos += 1; }
        JsonValue::Object(map)
    }

    fn parse_string(&mut self) -> String {
        if self.peek() == b'"' { self.pos += 1; }
        let mut result = String::new();
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == b'"' {
                self.pos += 1;
                break;
            } else if c == b'\\' {
                self.pos += 1;
                if self.pos < self.input.len() {
                    match self.input[self.pos] {
                        b'"' => result.push('"'),
                        b'\\' => result.push('\\'),
                        b'/' => result.push('/'),
                        b'n' => result.push('\n'),
                        b't' => result.push('\t'),
                        b'r' => result.push('\r'),
                        b'b' => result.push('\u{0008}'),
                        b'f' => result.push('\u{000C}'),
                        b'u' => {
                            if self.pos + 4 < self.input.len() {
                                let hex = std::str::from_utf8(&self.input[self.pos + 1..self.pos + 5]).unwrap_or("0000");
                                let code = u32::from_str_radix(hex, 16).unwrap_or(0);
                                result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                                self.pos += 4;
                            }
                        }
                        _ => {}
                    }
                    self.pos += 1;
                }
            } else {
                let byte = c;
                if byte < 0x80 {
                    result.push(byte as char);
                    self.pos += 1;
                } else if byte >= 0xF0 && self.pos + 3 < self.input.len() {
                    let code = ((self.input[self.pos] & 0x07) as u32) << 18
                        | ((self.input[self.pos + 1] & 0x3F) as u32) << 12
                        | ((self.input[self.pos + 2] & 0x3F) as u32) << 6
                        | ((self.input[self.pos + 3] & 0x3F) as u32);
                    result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    self.pos += 4;
                } else if byte >= 0xE0 && self.pos + 2 < self.input.len() {
                    let code = ((self.input[self.pos] & 0x0F) as u32) << 12
                        | ((self.input[self.pos + 1] & 0x3F) as u32) << 6
                        | ((self.input[self.pos + 2] & 0x3F) as u32);
                    result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    self.pos += 3;
                } else if byte >= 0xC0 && self.pos + 1 < self.input.len() {
                    let code = ((self.input[self.pos] & 0x1F) as u32) << 6
                        | ((self.input[self.pos + 1] & 0x3F) as u32);
                    result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    self.pos += 2;
                } else {
                    result.push(byte as char);
                    self.pos += 1;
                }
            }
        }
        result
    }

    fn parse_number(&mut self) -> JsonValue {
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos] as char;
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let num_str = std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("0");
        JsonValue::Number(num_str.parse::<f64>().unwrap_or(0.0))
    }
}

struct Product {
    name: String,
    price: f64,
}

fn extract_body(response: &str) -> &str {
    if let Some(idx) = response.find("\r\n\r\n") {
        &response[idx + 4..]
    } else if let Some(idx) = response.find("\n\n") {
        &response[idx + 2..]
    } else {
        ""
    }
}

fn get_object_field<'a>(obj: &'a [(String, JsonValue)], key: &str) -> Option<&'a JsonValue> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn parse_products(body: &str) -> Vec<Product> {
    let mut parser = JsonParser::new(body);
    let value = parser.parse_value();
    let mut products = Vec::new();
    if let JsonValue::Array(items) = &value {
        for item in items {
            if let JsonValue::Object(fields) = item {
                let name = match get_object_field(fields, "name") {
                    Some(JsonValue::String(s)) => s.clone(),
                    _ => String::new(),
                };
                let price = match get_object_field(fields, "price") {
                    Some(JsonValue::Number(n)) => *n,
                    _ => 0.0,
                };
                products.push(Product { name, price });
            }
        }
    }
    products
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");

    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    let mut response = Vec::new();
    let mut buf = [0u8; 8192];
    loop {
        match stream.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => response.extend_from_slice(&buf[..n]),
            Err(_) => break,
        }
    }

    let response_str = String::from_utf8_lossy(&response);
    let body = extract_body(&response_str);
    let products = parse_products(body);

    let mut filtered: Vec<Product> = products.into_iter().filter(|p| p.price > 50.00).collect();
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
    }
    println!();
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|p| p.price).sum();
    println!("Total: ${:.2}", total);
}
