use std::path::{Path, PathBuf};

fn read_file_stats(path: &Path) -> (usize, usize) {
    let mut file = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return (0, 0),
    };

    let mut buf = Vec::new();
    match file.read_to_end(&mut buf) {
        Ok(_) => {}
        Err(_) => return (0, 0),
    }

    let chars = buf.len();

    if chars == 0 {
        return (0, 0);
    }

    let mut lines = buf.iter().filter(|&&b| b == b'\n').count();
    if buf.last() != Some(&b'\n') {
        lines += 1;
    }

    (lines, chars)
}

fn walk(
    dir: &Path,
    root: &Path,
    visited: &mut HashSet<PathBuf>,
    files: &mut Vec<(String, usize, usize)>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let file_type = match entry.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };

        if file_type.is_symlink() {
            continue;
        }

        let path = entry.path();

        if file_type.is_dir() {
            let canonical = match fs::canonicalize(&path) {
                Ok(c) => c,
                Err(_) => continue,
            };

            if !visited.contains(&canonical) {
                visited.insert(canonical);
                walk(&path, root, visited, files);
            }
        } else if file_type.is_file() {
            let rel_path = path
                .strip_prefix(root)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/");

            let (lines, chars) = read_file_stats(&path);
            files.push((rel_path, lines, chars));
        }
    }
}

fn main() {
    let root = PathBuf::from(
        "<tmp>",
    );

    let mut visited_dirs: HashSet<PathBuf> = HashSet::new();
    let mut files: Vec<(String, usize, usize)> = Vec::new();

    if let Ok(canonical) = fs::canonicalize(&root) {
        visited_dirs.insert(canonical);
    }

    walk(&root, &root, &mut visited_dirs, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, usize, usize)>> = BTreeMap::new();

    for (rel_path, lines, chars) in &files {
        let p = Path::new(rel_path);
        let ext = p
            .extension()
            .map(|e| format!(".{}", e))
            .unwrap_or_else(|| String::new());
        groups
            .entry(ext)
            .or_default()
            .push((rel_path.clone(), *lines, *chars));
    }

    for group in groups.values_mut() {
        group.sort_by(|a, b| a.0.cmp(&b.0));
    }

    print!("=== File Tree Analysis ===\n");
    print!("\n");

    let mut total_files: usize = 0;
    let mut total_lines: usize = 0;
    let mut total_chars: usize = 0;

    for (ext, group) in &groups {
        let n_files = group.len();
        let n_lines: usize = group.iter().map(|f| f.1).sum();
        let n_chars: usize = group.iter().map(|f| f.2).sum();

        print!("Extension: {}\n", ext);
        print!("  Files: {}\n", n_files);
        print!("  Total Lines: {}\n", n_lines);
        print!("  Total Characters: {}\n", n_chars);

        for (rel_path, lines, chars) in group {
            print!("    {}: {} lines, {} chars\n", rel_path, lines, chars);
        }

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;
    }

    print!("\n");
    print!("Total: {} files, {} lines, {} characters\n", total_files, total_lines, total_chars);
}

