#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <float.h>

#define MAX_NAME 256
#define FILE_PATH "<tmp>"

typedef struct {
    char from[MAX_NAME];
    char to[MAX_NAME];
    double weight;
} Edge;

typedef struct {
    int to;
    double weight;
    struct AdjEdge *next;
} AdjEdge;

static void skip_ws(const char **p) {
    while (**p && (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r'))
        (*p)++;
}

static void parse_string(const char **p, char *out, int max) {
    skip_ws(p);
    if (**p != '"') { out[0] = '\0'; return; }
    (*p)++;
    int i = 0;
    while (**p && **p != '"' && i < max - 1) {
        if (**p == '\\') {
            (*p)++;
            if (**p) out[i++] = **p;
        } else {
            out[i++] = **p;
        }
        (*p)++;
    }
    out[i] = '\0';
    if (**p == '"') (*p)++;
}

static double parse_number(const char **p) {
    skip_ws(p);
    char *end;
    double val = strtod(*p, &end);
    *p = end;
    return val;
}

int main(void) {
    FILE *f = fopen(FILE_PATH, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open file\n");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long flen = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc((size_t)flen + 1);
    if (!buf) { fclose(f); return 1; }
    size_t rd = fread(buf, 1, (size_t)flen, f);
    buf[rd] = '\0';
    fclose(f);

    const char *p = buf;
    skip_ws(&p);
    if (*p == '{') p++;
    skip_ws(&p);

    /* Parse "nodes" */
    char key[MAX_NAME];
    parse_string(&p, key, MAX_NAME);
    skip_ws(&p);
    if (*p == ':') p++;
    skip_ws(&p);
    if (*p == '[') p++;

    int node_cap = 64, node_count = 0;
    char **nodes = malloc((size_t)node_cap * sizeof(char *));
    while (1) {
        skip_ws(&p);
        if (*p == ']') { p++; break; }
        if (*p == ',') { p++; continue; }
        if (*p == '\0') break;
        if (node_count >= node_cap) {
            node_cap *= 2;
            nodes = realloc(nodes, (size_t)node_cap * sizeof(char *));
        }
        char *name = malloc(MAX_NAME);
        parse_string(&p, name, MAX_NAME);
        nodes[node_count] = name;
        node_count++;
    }

    skip_ws(&p);
    if (*p == ',') p++;
    skip_ws(&p);

    /* Parse "edges" */
    parse_string(&p, key, MAX_NAME);
    skip_ws(&p);
    if (*p == ':') p++;
    skip_ws(&p);
    if (*p == '[') p++;

    int edge_cap = 128, edge_count = 0;
    Edge *edges = malloc((size_t)edge_cap * sizeof(Edge));
    while (1) {
        skip_ws(&p);
        if (*p == ']') { p++; break; }
        if (*p == ',') { p++; continue; }
        if (*p == '\0') break;
        if (edge_count >= edge_cap) {
            edge_cap *= 2;
            edges = realloc(edges, (size_t)edge_cap * sizeof(Edge));
        }
        if (*p == '{') p++;
        skip_ws(&p);
        parse_string(&p, key, MAX_NAME);
        skip_ws(&p);
        if (*p == ':') p++;
        parse_string(&p, edges[edge_count].from, MAX_NAME);
        skip_ws(&p);
        if (*p == ',') p++;
        skip_ws(&p);
        parse_string(&p, key, MAX_NAME);
        skip_ws(&p);
        if (*p == ':') p++;
        parse_string(&p, edges[edge_count].to, MAX_NAME);
        skip_ws(&p);
        if (*p == ',') p++;
        skip_ws(&p);
        parse_string(&p, key, MAX_NAME);
        skip_ws(&p);
        if (*p == ':') p++;
        edges[edge_count].weight = parse_number(&p);
        skip_ws(&p);
        if (*p == '}') p++;
        edge_count++;
    }

    /* Build adjacency list (undirected) */
    AdjEdge **adj = calloc((size_t)node_count, sizeof(AdjEdge *));
    for (int e = 0; e < edge_count; e++) {
        int fi = -1, ti = -1;
        for (int i = 0; i < node_count; i++) {
            if (fi < 0 && strcmp(nodes[i], edges[e].from) == 0) fi = i;
            if (ti < 0 && strcmp(nodes[i], edges[e].to) == 0) ti = i;
            if (fi >= 0 && ti >= 0) break;
        }
        if (fi < 0 || ti < 0) continue;

        AdjEdge *ae = malloc(sizeof(AdjEdge));
        ae->to = ti; ae->weight = edges[e].weight; ae->next = adj[fi];
        adj[fi] = ae;

        ae = malloc(sizeof(AdjEdge));
        ae->to = fi; ae->weight = edges[e].weight; ae->next = adj[ti];
        adj[ti] = ae;
    }

    /* Find source node "A" */
    int src = -1;
    for (int i = 0; i < node_count; i++) {
        if (strcmp(nodes[i], "A") == 0) { src = i; break; }
    }
    if (src < 0) {
        fprintf(stderr, "Node A not found\n");
        return 1;
    }

    /* Dijkstra */
    double *dist = malloc((size_t)node_count * sizeof(double));
    int *visited = calloc((size_t)node_count, sizeof(int));
    for (int i = 0; i < node_count; i++) dist[i] = INFINITY;
    dist[src] = 0.0;

    for (int iter = 0; iter < node_count; iter++) {
        int u = -1;
        double min_d = INFINITY;
        for (int i = 0; i < node_count; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u < 0) break;
        visited[u] = 1;
        AdjEdge *ae = adj[u];
        while (ae) {
            if (!visited[ae->to] && dist[u] + ae->weight < dist[ae->to]) {
                dist[ae->to] = dist[u] + ae->weight;
            }
            ae = ae->next;
        }
    }

    /* Sort nodes alphabetically */
    typedef struct { char *name; int idx; } NameIdx;
    NameIdx *ni = malloc((size_t)node_count * sizeof(NameIdx));
    for (int i = 0; i < node_count; i++) {
        ni[i].name = nodes[i];
        ni[i].idx = i;
    }
    for (int i = 0; i < node_count; i++) {
        for (int j = i + 1; j < node_count; j++) {
            if (strcmp(ni[i].name, ni[j].name) > 0) {
                NameIdx tmp = ni[i]; ni[i] = ni[j]; ni[j] = tmp;
            }
        }
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n");
    printf("\n");
    for (int i = 0; i < node_count; i++) {
        int idx = ni[i].idx;
        if (dist[idx] == INFINITY) {
            printf("A -> %s: infinity\n", ni[i].name);
        } else {
            double d = dist[idx];
            if (d == (double)(long long)d) {
                printf("A -> %s: %lld\n", ni[i].name, (long long)d);
            } else {
                printf("A -> %s: %g\n", ni[i].name, d);
            }
        }
    }

    /* Cleanup */
    free(buf);
    for (int i = 0; i < node_count; i++) free(nodes[i]);
    free(nodes);
    free(edges);
    for (int i = 0; i < node_count; i++) {
        AdjEdge *ae = adj[i];
        while (ae) { AdjEdge *nx = ae->next; free(ae); ae = nx; }
    }
    free(adj);
    free(dist);
    free(visited);
    free(ni);
    return 0;
}

