static void parse_string(const char **p, char *out, int max) {
    skip_ws(p);
    if (**p != '"') { out[0] = '\0'; return; }
    (*p)++;
    int i = 0;
    while (**p && **p != '"' && i < max - 1) {
        if (**p == '\\') {
            (*p)++;
            if (**p) out[i++] = **p;
        } else {
            out[i++] = **p;
        }
        (*p)++;
    }
    out[i] = '\0';
    if (**p == '"') (*p)++;
}

static double parse_number(const char **p) {
    skip_ws(p);
    char *end;
    double val = strtod(*p, &end);
    *p = end;
