            edges = realloc(edges, (size_t)edge_cap * sizeof(Edge));
        }
        if (*p == '{') p++;
        skip_ws(&p);
        parse_string(&p, key, MAX_NAME);
        skip_ws(&p);
        if (*p == ':') p++;
        parse_string(&p, edges[edge_count].from, MAX_NAME);
        skip_ws(&p);
        if (*p == ',') p++;
        skip_ws(&p);
        parse_string(&p, key, MAX_NAME);
        skip_ws(&p);
        if (*p == ':') p++;
