        for (int i = 0; i < node_count; i++) {
            if (fi < 0 && strcmp(nodes[i], edges[e].from) == 0) fi = i;
            if (ti < 0 && strcmp(nodes[i], edges[e].to) == 0) ti = i;
            if (fi >= 0 && ti >= 0) break;
        }
        if (fi < 0 || ti < 0) continue;

        AdjEdge *ae = malloc(sizeof(AdjEdge));
        ae->to = ti; ae->weight = edges[e].weight; ae->next = adj[fi];
        adj[fi] = ae;

        ae = malloc(sizeof(AdjEdge));
        ae->to = fi; ae->weight = edges[e].weight; ae->next = adj[ti];
        adj[ti] = ae;
    }

    /* Find source node "A" */
    int src = -1;
    for (int i = 0; i < node_count; i++) {
        if (strcmp(nodes[i], "A") == 0) { src = i; break; }
    }
    if (src < 0) {
        fprintf(stderr, "Node A not found\n");
        return 1;
    }

    /* Dijkstra */
    double *dist = malloc((size_t)node_count * sizeof(double));
    int *visited = calloc((size_t)node_count, sizeof(int));
    for (int i = 0; i < node_count; i++) dist[i] = INFINITY;
