        for (int i = 0; i < node_count; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u < 0) break;
        visited[u] = 1;
        AdjEdge *ae = adj[u];
        while (ae) {
            if (!visited[ae->to] && dist[u] + ae->weight < dist[ae->to]) {
                dist[ae->to] = dist[u] + ae->weight;
            }
            ae = ae->next;
        }
    }

    /* Sort nodes alphabetically */
    typedef struct { char *name; int idx; } NameIdx;
    NameIdx *ni = malloc((size_t)node_count * sizeof(NameIdx));
    for (int i = 0; i < node_count; i++) {
        ni[i].name = nodes[i];
        ni[i].idx = i;
    }
    for (int i = 0; i < node_count; i++) {
        for (int j = i + 1; j < node_count; j++) {
            if (strcmp(ni[i].name, ni[j].name) > 0) {
                NameIdx tmp = ni[i]; ni[i] = ni[j]; ni[j] = tmp;
            }
        }
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n");
    printf("\n");
    for (int i = 0; i < node_count; i++) {
        int idx = ni[i].idx;
        if (dist[idx] == INFINITY) {
            printf("A -> %s: infinity\n", ni[i].name);
        } else {
            double d = dist[idx];
            if (d == (double)(long long)d) {
                printf("A -> %s: %lld\n", ni[i].name, (long long)d);
            } else {
                printf("A -> %s: %g\n", ni[i].name, d);
            }
        }
    }

    /* Cleanup */
    free(buf);
    for (int i = 0; i < node_count; i++) free(nodes[i]);
    free(nodes);
    free(edges);
    for (int i = 0; i < node_count; i++) {
        AdjEdge *ae = adj[i];
        while (ae) { AdjEdge *nx = ae->next; free(ae); ae = nx; }
    }
    free(adj);
    free(dist);
    free(visited);
    free(ni);
    return 0;
}
