#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <netdb.h>
#include <ctype.h>

typedef struct {
    int id;
    char *name;
    double price;
    char *category;
    int stock;
} Product;

static char *skip_ws(const char **p) {
    const char *s = *p;
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    *p = s;
    return (char *)s;
}

static char *parse_string(const char **p) {
    const char *s = skip_ws(p);
    if (*s != '"') return NULL;
    s++;
    const char *start = s;
    size_t cap = 256;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) return NULL;
    buf[0] = '\0';

    while (*s != '"' && *s != '\0') {
        if (*s == '\\') {
            s++;
            if (*s == '\0') break;
            if (len + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, cap); if (!buf) return NULL; }
            switch (*s) {
                case '"': buf[len++] = '"'; break;
                case '\\': buf[len++] = '\\'; break;
                case '/': buf[len++] = '/'; break;
                case 'n': buf[len++] = '\n'; break;
                case 't': buf[len++] = '\t'; break;
                case 'r': buf[len++] = '\r'; break;
                case 'b': buf[len++] = '\b'; break;
                case 'f': buf[len++] = '\f'; break;
                case 'u': {
                    s++;
                    for (int i = 0; i < 4 && *s; i++) s++;
                    s--;
                    if (len + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, cap); if (!buf) return NULL; }
                    buf[len++] = '?';
                    break;
                }
                default: buf[len++] = *s; break;
            }
        } else {
            if (len + 1 >= cap) { cap *= 2; buf = (char *)realloc(buf, cap); if (!buf) return NULL; }
            buf[len++] = *s;
            s++;
        }
    }
    if (*s == '"') s++;
    *p = s;
    buf[len] = '\0';
    return buf;
}

static double parse_number(const char **p) {
    const char *s = skip_ws(p);
    char *end;
    double val = strtod(s, &end);
    *p = end;
    return val;
}

static int parse_int(const char **p) {
    const char *s = skip_ws(p);
    char *end;
    long val = strtol(s, &end, 10);
    *p = end;
    return (int)val;
}

static void parse_object(const char **p, Product *prod) {
    const char *s = skip_ws(p);
    if (*s != '{') { *p = s; return; }
    s++;
    *p = s;

    while (1) {
        s = skip_ws(p);
        if (*s == '}') { s++; *p = s; return; }
        if (*s == ',') { s++; *p = s; s = skip_ws(p); }
        if (*s == '\0') { *p = s; return; }

        char *key = parse_string(&s);
        if (!key) { *p = s; return; }

        s = skip_ws(&s);
        if (*s == ':') s++;
        *p = s;

        if (strcmp(key, "id") == 0) {
            prod->id = parse_int(&s);
        } else if (strcmp(key, "name") == 0) {
            free(prod->name);
            prod->name = parse_string(&s);
            if (!prod->name) prod->name = strdup("");
        } else if (strcmp(key, "price") == 0) {
            prod->price = parse_number(&s);
        } else if (strcmp(key, "category") == 0) {
            free(prod->category);
            prod->category = parse_string(&s);
            if (!prod->category) prod->category = strdup("");
        } else if (strcmp(key, "stock") == 0) {
            prod->stock = parse_int(&s);
        } else {
            s = skip_ws(&s);
            if (*s == '"') {
                parse_string(&s);
            } else if (*s == '{' || *s == '[') {
                int depth = 0;
                char open = *s;
                char close = (open == '{') ? '}' : ']';
                while (*s) {
                    if (*s == open) depth++;
                    else if (*s == close) { depth--; if (depth == 0) { s++; break; } }
                    else if (*s == '"') {
                        s++;
                        while (*s && *s != '"') { if (*s == '\\') s++; s++; }
                        if (*s == '"') s++;
                    }
                    s++;
                }
            } else if (*s == 't' || *s == 'f') {
                s += (*s == 't') ? 4 : 5;
            } else if (*s == 'n') {
                s += 4;
            } else {
                parse_number(&s);
            }
        }
        free(key);
        *p = s;
    }
}

static int compare_name(const void *a, const void *b) {
    const Product *pa = (const Product *)a;
    const Product *pb = (const Product *)b;
    return strcasecmp(pa->name, pb->name);
}

int main(void) {
    struct addrinfo hints, *result = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    if (getaddrinfo("127.0.0.1", "18923", &hints, &result) != 0) {
        fprintf(stderr, "getaddrinfo failed\n");
        return 1;
    }

    int sockfd = -1;
    struct addrinfo *rp;
    for (rp = result; rp; rp = rp->ai_next) {
        sockfd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (sockfd < 0) continue;
        if (connect(sockfd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(sockfd);
        sockfd = -1;
    }
    freeaddrinfo(result);

    if (sockfd < 0) {
        fprintf(stderr, "connect failed\n");
        return 1;
    }

    const char *req =
        "GET /api/products HTTP/1.1\r\n"
        "Host: 127.0.0.1:18923\r\n"
        "Accept: */*\r\n"
        "Connection: close\r\n"
        "\r\n";
    size_t reqlen = strlen(req);
    size_t sent = 0;
    while (sent < reqlen) {
        ssize_t n = write(sockfd, req + sent, reqlen - sent);
        if (n <= 0) { close(sockfd); return 1; }
        sent += (size_t)n;
    }

    size_t bufcap = 65536;
    char *buf = (char *)malloc(bufcap);
    if (!buf) { close(sockfd); return 1; }
    size_t len = 0;

    while (1) {
        if (len + 4096 >= bufcap) {
            bufcap *= 2;
            buf = (char *)realloc(buf, bufcap);
            if (!buf) { close(sockfd); return 1; }
        }
        ssize_t n = read(sockfd, buf + len, bufcap - len);
        if (n < 0) break;
        if (n == 0) break;
        len += (size_t)n;
    }
    close(sockfd);
    buf[len] = '\0';

    /* Find end of headers */
    char *header_end = strstr(buf, "\r\n\r\n");
    if (!header_end) header_end = strstr(buf, "\n\n");
    if (!header_end) {
        free(buf);
        fprintf(stderr, "no body found\n");
        return 1;
    }

    /* Compute body start before null-terminating */
    char *body;
    if (header_end[0] == '\r' && header_end[1] == '\n') body = header_end + 4;
    else body = header_end + 2;

    /* Null-terminate headers so strcasestr works on them */
    *header_end = '\0';

    int is_chunked = (strcasestr(buf, "transfer-encoding: chunked") != NULL);

    if (is_chunked) {
        char *decoded = (char *)malloc(len + 1);
        if (!decoded) { free(buf); return 1; }
        size_t dlen = 0;
        char *cp = body;
        while (1) {
            char *eol = strchr(cp, '\n');
            if (!eol) break;
            *eol = '\0';
            long csize = strtol(cp, NULL, 16);
            if (csize == 0) {
                cp = eol + 1;
                if (*cp == '\r') cp++;
                if (*cp == '\n') cp++;
                break;
            }
            cp = eol + 1;
            if (*cp == '\r') cp++;
            if (*cp == '\n') cp++;
            size_t space = len - (size_t)(cp - body);
            if ((size_t)csize > space) csize = (long)space;
            if (csize > 0) {
                memcpy(decoded + dlen, cp, (size_t)csize);
                dlen += (size_t)csize;
            }
            cp += (size_t)csize;
            if (cp[0] == '\r' && cp[1] == '\n') cp += 2;
            else if (cp[0] == '\n') cp += 1;
        }
        decoded[dlen] = '\0';
        free(buf);
        buf = decoded;
        body = buf;
        len = dlen;
    }

    /* Parse JSON array of products */
    Product *products = (Product *)malloc(sizeof(Product) * 1024);
    if (!products) { free(buf); return 1; }
    int max_products = 1024;
    int count = 0;

    const char *p = body;
    p = skip_ws(&p);
    if (*p != '[') {
        free(buf);
        free(products);
        fprintf(stderr, "expected array\n");
        return 1;
    }
    p++;

    while (1) {
        p = skip_ws(&p);
        if (*p == ']') { p++; break; }
        if (*p == '\0') break;
        if (*p == ',') { p++; p = skip_ws(&p); if (*p == ']') { p++; break; } if (*p == '\0') break; }
        if (*p != '{') { p++; continue; }

        if (count >= max_products) {
            max_products *= 2;
            products = (Product *)realloc(products, sizeof(Product) * max_products);
            if (!products) { free(buf); return 1; }
        }

        memset(&products[count], 0, sizeof(Product));
        parse_object(&p, &products[count]);
        if (!products[count].name) products[count].name = strdup("");
        if (!products[count].category) products[count].category = strdup("");
        count++;

        p = skip_ws(&p);
        if (*p == ']') { p++; break; }
        if (*p == '\0') break;
    }

    free(buf);

    /* Filter: price > 50.00 */
    Product *filtered = (Product *)malloc(sizeof(Product) * (count > 0 ? count : 1));
    if (!filtered) {
        for (int i = 0; i < count; i++) { free(products[i].name); free(products[i].category); }
        free(products);
        return 1;
    }
    int fcount = 0;
    for (int i = 0; i < count; i++) {
        if (products[i].price > 50.00) {
            filtered[fcount++] = products[i];
        }
    }

    /* Sort by name ascending */
    qsort(filtered, (size_t)fcount, sizeof(Product), compare_name);

    /* Print output */
    printf("=== Filtered Products (price > $50.00) ===\n");
    printf("\n");
    for (int i = 0; i < fcount; i++) {
        printf("%s: $%.2f\n", filtered[i].name, filtered[i].price);
    }
    printf("\n");
    printf("Count: %d\n", fcount);
    double total = 0.0;
    for (int i = 0; i < fcount; i++) {
        total += filtered[i].price;
    }
    printf("Total: $%.2f\n", total);

    /* Cleanup */
    for (int i = 0; i < fcount; i++) {
        free(filtered[i].name);
        free(filtered[i].category);
    }
    free(filtered);
    for (int i = 0; i < count; i++) {
        free(products[i].name);
        free(products[i].category);
    }
    free(products);

    return 0;
}
