use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};
use std::fs;

enum Json {
    Str(String),
    Num(i64),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser {
            data: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.data.len() {
            match self.data[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn expect(&mut self, c: u8) {
        self.skip_ws();
        assert_eq!(self.data[self.pos], c, "expected byte {} at {}", c, self.pos);
        self.pos += 1;
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut bytes = Vec::new();
        loop {
            let c = self.data[self.pos];
            self.pos += 1;
            if c == b'"' {
                break;
            }
            if c == b'\\' {
                let e = self.data[self.pos];
                self.pos += 1;
                match e {
                    b'"' => bytes.push(b'"'),
                    b'\\' => bytes.push(b'\\'),
                    b'/' => bytes.push(b'/'),
                    b'n' => bytes.push(b'\n'),
                    b't' => bytes.push(b'\t'),
                    b'r' => bytes.push(b'\r'),
                    b'b' => bytes.push(8),
                    b'f' => bytes.push(12),
                    b'u' => {
                        let mut v: u32 = 0;
                        for _ in 0..4 {
                            let h = self.data[self.pos];
                            self.pos += 1;
                            v = v * 16 + (h as char).to_digit(16).unwrap() as u32;
                        }
                        let ch = char::from_u32(v).unwrap_or('\u{FFFD}');
                        let mut buf = [0u8; 4];
                        bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                    }
                    _ => {}
                }
            } else {
                bytes.push(c);
            }
        }
        String::from_utf8(bytes).unwrap()
    }

    fn parse_number(&mut self) -> i64 {
        self.skip_ws();
        let mut s = String::new();
        while self.pos < self.data.len() {
            let c = self.data[self.pos] as char;
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        s.parse::<f64>().unwrap() as i64
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        let c = self.data[self.pos];
        match c {
            b'"' => Json::Str(self.parse_string()),
            b'[' => {
                self.pos += 1;
                let mut arr = Vec::new();
                self.skip_ws();
                if self.data[self.pos] == b']' {
                    self.pos += 1;
                    return Json::Arr(arr);
                }
                loop {
                    arr.push(self.parse_value());
                    self.skip_ws();
                    if self.data[self.pos] == b',' {
                        self.pos += 1;
                    } else {
                        self.expect(b']');
                        break;
                    }
                }
                Json::Arr(arr)
            }
            b'{' => {
                self.pos += 1;
                let mut obj = Vec::new();
                self.skip_ws();
                if self.data[self.pos] == b'}' {
                    self.pos += 1;
                    return Json::Obj(obj);
                }
                loop {
                    let k = self.parse_string();
                    self.expect(b':');
                    let v = self.parse_value();
                    obj.push((k, v));
                    self.skip_ws();
                    if self.data[self.pos] == b',' {
                        self.pos += 1;
                    } else {
                        self.expect(b'}');
                        break;
                    }
                }
                Json::Obj(obj)
            }
            b't' => {
                self.pos += 4;
                Json::Num(1)
            }
            b'f' => {
                self.pos += 5;
                Json::Num(0)
            }
            b'n' => {
                self.pos += 4;
                Json::Num(0)
            }
            _ => Json::Num(self.parse_number()),
        }
    }
}

#[derive(PartialEq, Eq)]
struct State {
    d: i64,
    n: String,
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.d.cmp(&other.d)
    }
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.d.cmp(&other.d)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("failed to read graph.json");
    let mut p = Parser::new(&content);
    let root = p.parse_value();

    let mut nodes: Vec<String> = Vec::new();
    let mut edges: Vec<(String, String, i64)> = Vec::new();

    if let Json::Obj(obj) = root {
        for (k, v) in obj {
            match k.as_str() {
                "nodes" => {
                    if let Json::Arr(a) = v {
                        for n in a {
                            if let Json::Str(s) = n {
                                nodes.push(s);
                            }
                        }
                    }
                }
                "edges" => {
                    if let Json::Arr(a) = v {
                        for e in a {
                            if let Json::Obj(oo) = e {
                                let mut from = String::new();
                                let mut to = String::new();
                                let mut w = 0i64;
                                for (k2, v2) in oo {
                                    match k2.as_str() {
                                        "from" => {
                                            if let Json::Str(s) = v2 {
                                                from = s.clone();
                                            }
                                        }
                                        "to" => {
                                            if let Json::Str(s) = v2 {
                                                to = s.clone();
                                            }
                                        }
                                        "weight" => {
                                            if let Json::Num(n) = v2 {
                                                w = *n;
                                            }
                                        }
                                        _ => {}
                                    }
                                }
                                edges.push((from, to, w));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }

    // Collect all nodes (including any appearing only in edges).
    let mut all: Vec<String> = nodes.clone();
    for (f, t, _) in &edges {
        if !all.contains(f) {
            all.push(f.clone());
        }
        if !all.contains(t) {
            all.push(t.clone());
        }
    }

    // Build undirected adjacency list.
    let mut adj: HashMap<String, Vec<(String, i64)>> = HashMap::new();
    for n in &all {
        adj.entry(n.clone()).or_insert_with(Vec::new);
    }
    for (f, t, w) in &edges {
        adj.get_mut(f).unwrap().push((t.clone(), *w));
        adj.get_mut(t).unwrap().push((f.clone(), *w));
    }

    // Dijkstra from "A".
    let start = "A".to_string();
    let mut dist: HashMap<String, i64> = HashMap::new();
    for n in &all {
        dist.insert(n.clone(), i64::MAX);
    }
    dist.insert(start.clone(), 0);

    let mut heap: BinaryHeap<Reverse<State>> = BinaryHeap::new();
    heap.push(Reverse(State {
        d: 0,
        n: start.clone(),
    }));

    while let Some(Reverse(st)) = heap.pop() {
        let d = st.d;
        let n = st.n;
        if d > *dist.get(&n).unwrap() {
            continue; // stale entry
        }
        for (m, w) in adj.get(&n).unwrap() {
            let nd = d + w;
            if nd < *dist.get(m).unwrap() {
                dist.insert(m.clone(), nd);
                heap.push(Reverse(State {
                    d: nd,
                    n: m.clone(),
                }));
            }
        }
    }

    let mut sorted = all.clone();
    sorted.sort();

    println!("=== Shortest Paths from A ===");
    println!();
    for n in &sorted {
        let d = *dist.get(n).unwrap();
        if d == i64::MAX {
            println!("A -> {}: unreachable", n);
        } else {
            println!("A -> {}: {}", n, d);
        }
    }
}

