#include <errno.h>

#define BASE_DIR "<tmp>"

typedef struct {
    char *relpath;
    char *ext;
    long lines;
    long chars;
} FileEntry;

static FileEntry *files = NULL;
static int file_count = 0;
static int file_capacity = 0;

typedef struct {
    dev_t dev;
    ino_t ino;
} DirKey;

static DirKey *visited = NULL;
static int visited_count = 0;
static int visited_capacity = 0;

static int is_visited(dev_t dev, ino_t ino) {
    for (int i = 0; i < visited_count; i++) {
        if (visited[i].dev == dev && visited[i].ino == ino) return 1;
    }
    return 0;
}

static void mark_visited(dev_t dev, ino_t ino) {
    if (visited_count == visited_capacity) {
        visited_capacity = visited_capacity ? visited_capacity * 2 : 256;
        visited = realloc(visited, (size_t)visited_capacity * sizeof(DirKey));
        if (!visited) exit(1);
    }
    visited[visited_count].dev = dev;
    visited[visited_count].ino = ino;
    visited_count++;
}

static void add_file(const char *relpath, const char *ext, long lines, long chars) {
    if (file_count == file_capacity) {
        file_capacity = file_capacity ? file_capacity * 2 : 128;
        files = realloc(files, (size_t)file_capacity * sizeof(FileEntry));
        if (!files) exit(1);
    }
    files[file_count].relpath = strdup(relpath);
    files[file_count].ext = strdup(ext);
    files[file_count].lines = lines;
    files[file_count].chars = chars;
    if (!files[file_count].relpath || !files[file_count].ext) exit(1);
    file_count++;
}

static void count_file(const char *fullpath, long *lines, long *chars) {
    FILE *f = fopen(fullpath, "rb");
    if (!f) { *lines = 0; *chars = 0; return; }
    *lines = 0;
    *chars = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        (*chars)++;
        if (c == '\n') (*lines)++;
    }
    fclose(f);
}

static void get_extension(const char *filename, char *extbuf, size_t extbufsize) {
    const char *dot = strrchr(filename, '.');
    if (dot && dot != filename) {
        size_t len = (size_t)(filename + strlen(filename) - dot);
        if (len >= extbufsize) len = extbufsize - 1;
        memcpy(extbuf, dot, len);
        extbuf[len] = '\0';
    } else {
        extbuf[0] = '\0';
    }
}

static char *build_path(const char *dirpath, const char *name) {
    size_t dlen = strlen(dirpath);
    size_t nlen = strlen(name);
    char *buf = malloc(dlen + 1 + nlen + 1);
    if (!buf) exit(1);
    if (dlen > 0 && dirpath[dlen - 1] != '/')
        snprintf(buf, dlen + 1 + nlen + 1, "%s/%s", dirpath, name);
    else
        snprintf(buf, dlen + 1 + nlen + 1, "%s%s", dirpath, name);
    return buf;
}

static char *build_relpath(const char *relprefix, const char *name) {
    size_t plen = strlen(relprefix);
    size_t nlen = strlen(name);
    char *buf = malloc(plen + 1 + nlen + 1);
    if (!buf) exit(1);
    if (plen > 0)
        snprintf(buf, plen + 1 + nlen + 1, "%s/%s", relprefix, name);
    else
        snprintf(buf, plen + 1 + nlen + 1, "%s", name);
    return buf;
}

static void walk_dir(const char *dirpath, const char *relprefix) {
    struct stat st;
    if (lstat(dirpath, &st) != 0) return;
    if (is_visited(st.st_dev, st.st_ino)) return;
    mark_visited(st.st_dev, st.st_ino);
    if (!S_ISDIR(st.st_mode)) return;

    DIR *d = opendir(dirpath);
    if (!d) return;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char *fullpath = build_path(dirpath, entry->d_name);
        char *relpath = build_relpath(relprefix, entry->d_name);

        struct stat est;
        if (lstat(fullpath, &est) == 0) {
