static void mark_visited(dev_t dev, ino_t ino) {
    if (visited_count == visited_capacity) {
        visited_capacity = visited_capacity ? visited_capacity * 2 : 256;
        visited = realloc(visited, (size_t)visited_capacity * sizeof(DirKey));
        if (!visited) exit(1);
